#:property PublishAot=false
#:package Microsoft.CodeAnalysis.CSharp@4.14.0
// Run with .NET 10: dotnet run .github/scripts/check_documentation.cs -- src
// Add --inventory <path.json> to export the declarations for a documentation review.
// This syntax audit checks both target-framework branches and internal APIs, which CS1591
// does not cover. It checks tag presence and XML structure, not prose accuracy, exception-tag
// coverage, or inline rationale; those require source review. Explicit throws are exported only
// as review candidates. Generated code, build outputs, and private non-callable members are skipped.
// Full-member inheritdoc is accepted when it names a source or has a plausible inheritance site.
// This is not symbol resolution: cref existence, matching source signatures, inherited text, and
// arbitrary XPath selections still require the compiler/documentation renderer and human review.
// Filtered top-level inheritdoc does not waive local contract tags. Conditional symbols outside
// the NET8/NET10 sets below are not modeled; the normal project builds remain necessary.
using System.Text.Json;
using System.Xml.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

string? requestedDirectory = null;
string? inventoryPath = null;
for (int argumentIndex = 0; argumentIndex < args.Length; argumentIndex++)
{
    // Parse option values before enumerating source so a missing output path or unknown flag
    // cannot silently turn into an unintended source directory or overwrite a source file.
    string argument = args[argumentIndex];
    if (argument == "--inventory")
    {
        if (inventoryPath is not null || argumentIndex + 1 >= args.Length
            || args[argumentIndex + 1].StartsWith("--", StringComparison.Ordinal))
        {
            Console.Error.WriteLine("--inventory requires one output path and may only be specified once.");
            return 2;
        }
        inventoryPath = args[++argumentIndex];
    }
    else if (argument.StartsWith("--", StringComparison.Ordinal) || requestedDirectory is not null)
    {
        Console.Error.WriteLine("Usage: dotnet run check_documentation.cs -- [source-directory] [--inventory output.json]");
        return 2;
    }
    else requestedDirectory = argument;
}
string directory = requestedDirectory ?? "src";
if (!Directory.Exists(directory))
{
    Console.Error.WriteLine($"Source directory does not exist: {directory}");
    return 2;
}
if (inventoryPath is not null && Path.GetExtension(inventoryPath).Equals(".cs", StringComparison.OrdinalIgnoreCase))
{
    Console.Error.WriteLine("Inventory output must not overwrite a C# source file.");
    return 2;
}
var inventory = new List<object>();
var issues = new SortedSet<string>(StringComparer.Ordinal);
var seen = new HashSet<string>(StringComparer.Ordinal);
int declarations = 0;
foreach (string file in Directory.EnumerateFiles(directory, "*.cs", SearchOption.AllDirectories).Order())
{
    // Generated build outputs belong to their generator, not to the maintained source contract.
    if (file.Replace('\\', '/').Split('/').Any(p => p is "obj" or "bin")) continue;
    string source = File.ReadAllText(file);
    if (source.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)) continue;
    foreach (string framework in new[] { "NET8_0", "NET10_0" })
    {
        var symbols = framework == "NET10_0"
            ? new[] { "NET", "NET8_0_OR_GREATER", "NET9_0_OR_GREATER", "NET10_0_OR_GREATER", framework }
            : new[] { "NET", "NET8_0_OR_GREATER", framework };
        var tree = CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Preview,
            DocumentationMode.Diagnose, preprocessorSymbols: symbols), file);
        foreach (var node in tree.GetRoot().DescendantNodes().OfType<MemberDeclarationSyntax>())
        {
            if (node is BaseNamespaceDeclarationSyntax or GlobalStatementSyntax) continue;
            bool callable = node is BaseMethodDeclarationSyntax or DelegateDeclarationSyntax;
            bool privateMember = node.Modifiers.Any(SyntaxKind.PrivateKeyword);
            if (privateMember && !callable) continue;
            // An unqualified field/property in a class is private. Interface members and enum
            // values have implicit public contracts, so visibility cannot use keywords alone.
            bool implicitPrivate = !node.Modifiers.Any(m => m.IsKind(SyntaxKind.PublicKeyword)
                || m.IsKind(SyntaxKind.InternalKeyword) || m.IsKind(SyntaxKind.ProtectedKeyword))
                && node.Parent is TypeDeclarationSyntax parent && parent is not InterfaceDeclarationSyntax;
            if (implicitPrivate && !callable && node is not BaseTypeDeclarationSyntax) continue;
            int line = tree.GetLineSpan(node.Span).StartLinePosition.Line + 1;
            var doc = node.GetLeadingTrivia().Select(t => t.GetStructure())
                .OfType<DocumentationCommentTriviaSyntax>().LastOrDefault();
            string docText = doc?.ToFullString() ?? "";
            // A declaration can begin at the same offset in both frameworks yet have different
            // active parameter tokens under #if. Deduplicate only identical active syntax and docs.
            string activeTokens = string.Join("\0", node.DescendantTokens().Select(token => token.RawKind + ":" + token.Text));
            string key = file + ":" + node.SpanStart + ":" + activeTokens + ":" + docText;
            if (!seen.Add(key)) continue;
            declarations++;
            string xml = string.Join("\n", docText.Split('\n').Select(s =>
                s.TrimStart().StartsWith("///") ? s.TrimStart()[3..] : s));
            XElement? parsed = null;
            try { parsed = XElement.Parse("<docs>" + xml + "</docs>"); }
            catch (System.Xml.XmlException) { issues.Add($"{file}:{line}: malformed XML"); }
            bool implicitInheritanceSite = node.Modifiers.Any(SyntaxKind.OverrideKeyword)
                || node is MethodDeclarationSyntax { ExplicitInterfaceSpecifier: not null }
                || node is PropertyDeclarationSyntax { ExplicitInterfaceSpecifier: not null }
                || node is EventDeclarationSyntax { ExplicitInterfaceSpecifier: not null }
                || node is IndexerDeclarationSyntax { ExplicitInterfaceSpecifier: not null }
                || node is TypeDeclarationSyntax { BaseList: not null }
                || node is not ConstructorDeclarationSyntax && node.Parent is TypeDeclarationSyntax { BaseList: not null };
            bool inherited = parsed?.Elements("inheritdoc").Any(tag => tag.Attribute("path") is null
                && (!string.IsNullOrWhiteSpace((string?)tag.Attribute("cref")) || implicitInheritanceSite)) == true;
            if (parsed?.Elements("inheritdoc").Any(tag => tag.Attribute("path") is null
                && string.IsNullOrWhiteSpace((string?)tag.Attribute("cref")) && !implicitInheritanceSite) == true)
                issues.Add($"{file}:{line}: inheritdoc has no explicit source or inheritance site");
            var parameters = node switch
            {
                BaseMethodDeclarationSyntax m => m.ParameterList.Parameters.ToArray(),
                DelegateDeclarationSyntax d => d.ParameterList.Parameters.ToArray(),
                RecordDeclarationSyntax r => r.ParameterList?.Parameters.ToArray() ?? [],
                ClassDeclarationSyntax c => c.ParameterList?.Parameters.ToArray() ?? [],
                StructDeclarationSyntax s => s.ParameterList?.Parameters.ToArray() ?? [],
                IndexerDeclarationSyntax i => i.ParameterList.Parameters.ToArray(),
                _ => Array.Empty<ParameterSyntax>()
            };
            var typeParameters = node switch
            {
                TypeDeclarationSyntax t => t.TypeParameterList?.Parameters.ToArray() ?? [],
                MethodDeclarationSyntax m => m.TypeParameterList?.Parameters.ToArray() ?? [],
                DelegateDeclarationSyntax d => d.TypeParameterList?.Parameters.ToArray() ?? [],
                _ => Array.Empty<TypeParameterSyntax>()
            };
            string? returnType = node switch
            {
                MethodDeclarationSyntax m => m.ReturnType.ToString(),
                OperatorDeclarationSyntax o => o.ReturnType.ToString(),
                ConversionOperatorDeclarationSyntax c => c.Type.ToString(),
                DelegateDeclarationSyntax d => d.ReturnType.ToString(),
                IndexerDeclarationSyntax i => i.Type.ToString(),
                _ => null
            };
            var missing = new List<string>();
            if (!inherited)
            {
                if (parsed?.Element("summary") is not { } summary || string.IsNullOrWhiteSpace(summary.Value))
                    missing.Add("summary");
                if (returnType is not null and not "void" && (parsed?.Element("returns") is not { } returns || string.IsNullOrWhiteSpace(returns.Value)))
                    missing.Add("returns");
            }
            // An incomplete local list can hide inherited parameter contracts in documentation
            // consumers. Require complete local lists when customizing them, independently of
            // renderer merge behavior; a pure full-member inheritdoc can inherit the whole list.
            if (!inherited || parsed?.Elements("param").Any() == true)
                foreach (var parameter in parameters)
                    if (parsed?.Elements("param").Any(p => (string?)p.Attribute("name") == parameter.Identifier.ValueText && !string.IsNullOrWhiteSpace(p.Value)) != true)
                        missing.Add("param:" + parameter.Identifier.ValueText);
            if (!inherited || parsed?.Elements("typeparam").Any() == true)
                foreach (var parameter in typeParameters)
                    if (parsed?.Elements("typeparam").Any(p => (string?)p.Attribute("name") == parameter.Identifier.ValueText && !string.IsNullOrWhiteSpace(p.Value)) != true)
                        missing.Add("typeparam:" + parameter.Identifier.ValueText);
            foreach (var tag in parsed?.Elements("param") ?? [])
                if (!parameters.Any(p => p.Identifier.ValueText == (string?)tag.Attribute("name")))
                    issues.Add($"{file}:{line}: unknown param:{tag.Attribute("name")?.Value}");
            foreach (var tag in parsed?.Elements("typeparam") ?? [])
                if (!typeParameters.Any(p => p.Identifier.ValueText == (string?)tag.Attribute("name")))
                    issues.Add($"{file}:{line}: unknown typeparam:{tag.Attribute("name")?.Value}");
            foreach (string missingPart in missing) issues.Add($"{file}:{line}: missing {missingPart}");
            // Explicit throws are review candidates, not a claim about exception escape: a catch
            // can consume them, while delegates and external providers can throw additional types.
            var throws = node.DescendantNodes(n => n == node || n is not MemberDeclarationSyntax)
                .Where(n => n is ThrowStatementSyntax or ThrowExpressionSyntax)
                .Select(n => n.ToString()).Distinct().ToArray();
            string name = node switch
            {
                BaseTypeDeclarationSyntax t => t.Identifier.ValueText,
                MethodDeclarationSyntax m => m.Identifier.ValueText,
                ConstructorDeclarationSyntax c => c.Identifier.ValueText,
                DestructorDeclarationSyntax d => d.Identifier.ValueText,
                DelegateDeclarationSyntax d => d.Identifier.ValueText,
                PropertyDeclarationSyntax p => p.Identifier.ValueText,
                EventDeclarationSyntax e => e.Identifier.ValueText,
                EnumMemberDeclarationSyntax e => e.Identifier.ValueText,
                BaseFieldDeclarationSyntax f => string.Join(",", f.Declaration.Variables.Select(v => v.Identifier.ValueText)),
                IndexerDeclarationSyntax => "this",
                OperatorDeclarationSyntax o => "operator " + o.OperatorToken.Text,
                ConversionOperatorDeclarationSyntax c => "operator " + c.Type,
                _ => node.Kind().ToString()
            };
            inventory.Add(new { file, framework, name, owner = (node.Parent as BaseTypeDeclarationSyntax)?.Identifier.ValueText,
                line, start = node.SpanStart, fullStart = node.FullSpan.Start,
                docEnd = doc?.ParentTrivia.FullSpan.End,
                length = node.Span.Length, kind = node.Kind().ToString(),
                signature = node.ToString().Split('{')[0].Split("=>")[0].Trim(),
                parameters = parameters.Select(p => new { name = p.Identifier.ValueText, type = p.Type?.ToString(), defaultValue = p.Default?.Value.ToString() }),
                typeParameters = typeParameters.Select(p => p.Identifier.ValueText), returnType, doc = docText,
                inherited, missing, throws });
        }
    }
}
if (inventoryPath is not null)
{
    File.WriteAllText(inventoryPath, JsonSerializer.Serialize(inventory, new JsonSerializerOptions { WriteIndented = true }));
}
foreach (string issue in issues) Console.WriteLine(issue);
Console.WriteLine($"Checked {declarations} declarations; {issues.Count} documentation issues.");
return issues.Count == 0 && declarations > 0 ? 0 : 1;
